_review" minlength="10" maxlength="1000" aria-label="<?= __t('Release agreement reference','مرجع توافق ختم حق شریک','د موافقې مرجع') ?>"></textarea></details><?php endif ?><button class="btn btn-primary"><?= __t('Request transfer','درخواست انتقال','لېږد وغواړئ') ?></button></form></section>
<section class="card modern-form"><h3><?= __t('Physical inventory count','شمارش واقعی موجودی','د موجودۍ شمېرنه') ?></h3><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="approve_count"><label><?= __t('Item','جنس','توکی') ?><?php doc_stock_select($items) ?></label><label><?= __t('Actual healthy quantity','مقدار واقعی سالم','د روغو توکو مقدار') ?><input class="form-control" name="actual" type="number" min="0" step="0.001" required></label><label><?= __t('Reason','دلیل اختلاف','د توپیر لامل') ?><textarea class="form-control" name="reason" minlength="3" maxlength="500" required></textarea></label><button class="btn btn-primary"><?= __t('Approve adjustment','تأیید تعدیل','سمون تایید') ?></button></form></section></div>
<section class="card modern-form"><h3><?= __t('Transfers awaiting receipt','انتقال‌های در انتظار دریافت','د ترلاسه کولو په تمه لېږدونه') ?></h3><?php $q=$pdo->prepare("SELECT t.*,s.name AS item_name FROM inventory_transfers t JOIN stock s ON s.id=t.stock_id WHERE t.destination_shop_id=? AND t.status='pending' ORDER BY t.id DESC");$q->execute([shop_id()]);foreach($q->fetchAll() as $t):?><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="approve_transfer"><input type="hidden" name="transfer_id" value="<?= (int)$t['id'] ?>"><span><?= sanitize('#'.$t['id'].' · '.$t['item_name'].' · '.$t['quantity']) ?></span><button class="btn btn-primary"><?= __t('Confirm receipt','تأیید دریافت','ترلاسه کول تایید') ?></button></form><?php endforeach ?></section>
<section class="card modern-form"><h3><?= __t('Pending transfer decisions','تصمیم انتقال‌های در انتظار','د لېږد پرېکړې') ?></h3><?php $dq=$pdo->prepare("SELECT id,source_shop_id,destination_shop_id,quantity FROM inventory_transfers WHERE (source_shop_id=? OR destination_shop_id=?) AND status='pending' ORDER BY id DESC");$dq->execute([shop_id(),shop_id()]);foreach($dq->fetchAll() as $t):?><form method="post"><?= csrf_field() ?><input name="transfer_id" type="hidden" value="<?= (int)$t['id'] ?>"><input name="action" type="hidden" value="<?= (int)$t['source_shop_id']===shop_id()?'edit_cancel':'approve_reject' ?>"><span><?= sanitize('#'.$t['id'].' · '.$t['quantity']) ?></span><button class="btn btn-secondary"><?= (int)$t['source_shop_id']===shop_id()?__t('Cancel request','لغو درخواست','غوښتنه لغوه'):__t('Reject receipt','رد دریافت','ترلاسه کول رد') ?></button></form><?php endforeach ?></section>
<section class="card modern-form table-responsive"><h3><?= __t('Inventory movement history','تاریخچهٔ گردش جنس','د توکو د حرکت تاریخ') ?></h3><table class="table"><thead><tr><?php foreach([__t('Date','تاریخ','نېټه'),__t('Item','جنس','توکی'),__t('Document','سند','سند'),__t('Quantity change','تغییر مقدار','د مقدار بدلون'),__t('Value change','تغییر ارزش','د ارزښت بدلون')] as $h):?><th><?= $h ?></th><?php endforeach ?></tr></thead><tbody><?php foreach($history as $m):?><tr><td><?= sanitize($m['created_at']) ?></td><td><?= sanitize($m['name']??'#'.$m['stock_id']) ?></td><td><?= sanitize($m['document_type'].' #'.$m['document_id']) ?></td><td><?= sanitize($m['quantity_delta']) ?></td><td><?= sanitize($m['value_delta'].' '.$m['currency_code']) ?></td></tr><?php endforeach ?></tbody></table><p><?= __t('Movement history begins with this update; earlier documents remain in their original archives.','گردش جنس از این اپدیت ثبت می‌شود؛ اسناد قبلی در آرشیف خود محفوظ‌اند.','د توکو حرکت له دې تازه کولو پیلېږي.') ?></p></section>
